import axios from "axios";
import React, { useEffect, useState } from "react";
import { Link, useNavigate } from "react-router-dom";
import {
  FiSearch,
  FiEye,
  FiRefreshCw,
  FiFileText,
  FiUser,
  FiPhone,
  FiMail,
  FiMapPin,
  FiExternalLink,
  FiPackage,
  FiCheckCircle,
  FiXCircle,
  FiClock,
  FiDollarSign,
  FiX,
  FiAlertCircle,
  FiChevronLeft,
  FiChevronRight,
  FiShoppingBag,
} from "react-icons/fi";

const AdminProductRequestsLayer = () => {
  const navigate = useNavigate();

  const [loading, setLoading] = useState(true);
  const [requests, setRequests] = useState([]);
  const [metrics, setMetrics] = useState({
    total: 0,
    PENDING: 0,
    CONFIRMED: 0,
    PROCESSING: 0,
    COMPLETED: 0,
    EXPIRED: 0,
    CANCELLED: 0,
  });
  const [pagination, setPagination] = useState({
    total: 0,
    page: 1,
    limit: 10,
    totalPages: 1,
  });

  const [searchQuery, setSearchQuery] = useState("");
  const [statusFilter, setStatusFilter] = useState("ALL");
  const [selectedRequest, setSelectedRequest] = useState(null);
  const [showDetailModal, setShowDetailModal] = useState(false);

  // Fetch product requests from backend API
  const fetchProductRequests = async (page = 1) => {
    try {
      setLoading(true);
      const params = {
        page,
        limit: pagination.limit || 10,
        status: statusFilter,
      };
      if (searchQuery.trim()) {
        params.search = searchQuery.trim();
      }

      const res = await axios.get(
        `${process.env.REACT_APP_BACKEND_URL}/api/productRequest/admin/all-requests`,
        { params }
      );

      if (res.data.success) {
        setRequests(res.data.requests || []);
        if (res.data.pagination) {
          setPagination(res.data.pagination);
        }
        if (res.data.metrics) {
          setMetrics(res.data.metrics);
        }
      }
    } catch (err) {
      console.error("Error fetching admin product requests:", err);
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProductRequests(1);
  }, [statusFilter]);

  // Handle Search submit
  const handleSearchSubmit = (e) => {
    e.preventDefault();
    fetchProductRequests(1);
  };

  // Lock body scroll when modal is open
  useEffect(() => {
    if (showDetailModal) {
      document.body.style.overflow = "hidden";
    } else {
      document.body.style.overflow = "auto";
    }
    return () => {
      document.body.style.overflow = "auto";
    };
  }, [showDetailModal]);

  const formatDate = (dateVal) => {
    if (!dateVal) return "N/A";
    const d = new Date(dateVal);
    return d.toLocaleString("en-IN", {
      day: "2-digit",
      month: "short",
      year: "numeric",
      hour: "2-digit",
      minute: "2-digit",
      hour12: true,
    });
  };

  const getStatusBadge = (status) => {
    const s = String(status || "").toUpperCase();
    switch (s) {
      case "PENDING":
        return <span className="badge bg-warning text-dark px-2.5 py-1.5 fs-12">Pending</span>;
      case "CONFIRMED":
        return <span className="badge bg-info text-dark px-2.5 py-1.5 fs-12">Confirmed</span>;
      case "PROCESSING":
        return <span className="badge bg-primary px-2.5 py-1.5 fs-12">Processing</span>;
      case "OUT_FOR_DELIVERY":
        return <span className="badge bg-primary px-2.5 py-1.5 fs-12">Out For Delivery</span>;
      case "DELIVERED":
      case "COMPLETED":
        return <span className="badge bg-success px-2.5 py-1.5 fs-12">Completed</span>;
      case "EXPIRED":
        return <span className="badge bg-danger px-2.5 py-1.5 fs-12">Expired</span>;
      case "CANCELLED":
      case "REJECTED":
        return <span className="badge bg-secondary px-2.5 py-1.5 fs-12">Cancelled</span>;
      default:
        return <span className="badge bg-light text-dark border px-2.5 py-1.5 fs-12">{status || "Pending"}</span>;
    }
  };

  // Helper to dynamically route Buyer Name click to the appropriate Tab & Status in /userBooking/:id
  const getBuyerTargetLocation = (buyerId, reqItem) => {
    if (!buyerId) return "#";
    const st = String(reqItem?.status || "").toUpperCase();

    if (st === "CONFIRMED" || st === "PROCESSING") {
      return {
        pathname: `/userBooking/${buyerId}`,
        search: "?tab=orders&status=CONFIRMED",
        state: { tab: "orders", status: "CONFIRMED" },
      };
    }
    if (st === "OUT_FOR_DELIVERY") {
      return {
        pathname: `/userBooking/${buyerId}`,
        search: "?tab=orders&status=OUT_FOR_DELIVERY",
        state: { tab: "orders", status: "OUT_FOR_DELIVERY" },
      };
    }
    if (st === "COMPLETED" || st === "DELIVERED") {
      return {
        pathname: `/userBooking/${buyerId}`,
        search: "?tab=orders&status=COMPLETED",
        state: { tab: "orders", status: "COMPLETED" },
      };
    }
    if (st === "EXPIRED" || reqItem?.isExpired) {
      return {
        pathname: `/userBooking/${buyerId}`,
        search: "?tab=requests&status=EXPIRED",
        state: { tab: "requests", status: "EXPIRED" },
      };
    }
    // Default to requests tab with PENDING
    return {
      pathname: `/userBooking/${buyerId}`,
      search: "?tab=requests&status=PENDING",
      state: { tab: "requests", status: "PENDING" },
    };
  };

  // Status Filter Tabs List
  const statusTabs = [
    { label: "All Requests", value: "ALL", count: metrics.total },
    { label: "Pending", value: "PENDING", count: metrics.PENDING },
    { label: "Expired", value: "EXPIRED", count: metrics.EXPIRED },
    { label: "Confirmed", value: "CONFIRMED", count: metrics.CONFIRMED },
    { label: "Out for Delivery", value: "OUT_FOR_DELIVERY", count: metrics.OUT_FOR_DELIVERY },
    { label: "Completed", value: "COMPLETED", count: metrics.COMPLETED },
  ];

  return (
    <div className="card common-card border border-gray-five" style={{ borderRadius: "12px" }}>
      {/* Header & Page Title */}
      <div className="card-header p-4 border-bottom bg-white d-flex flex-wrap align-items-center justify-content-between gap-3">
        <div>
          <h4 className="fw-bold text-dark mb-1 d-flex align-items-center gap-2">
            <FiShoppingBag className="text-primary" /> Product Requests Management
          </h4>
          <p className="text-muted fs-13 m-0">
            Monitor and manage all customer product and prescription requests, submitted quotations, and fulfillment status.
          </p>
        </div>

        <button
          type="button"
          className="btn btn-sm d-flex align-items-center gap-2 rounded-pill px-3.5 py-2 shadow-sm"
          style={{
            backgroundColor: "#ffffff",
            color: "#1e293b",
            border: "1px solid #cbd5e1",
            fontWeight: "600",
            fontSize: "13px",
            transition: "all 0.2s ease",
          }}
          onClick={() => fetchProductRequests(pagination.page)}
          title="Refresh Data"
        >
          <FiRefreshCw size={14} className={loading ? "spin" : ""} style={{ color: "#715DF2" }} />
          <span style={{ color: "#1e293b", fontWeight: "600", fontSize: "13px" }}>Refresh</span>
        </button>
      </div>

      {/* Filter Tabs & Search Bar */}
      <div className="p-4 border-bottom bg-light">
        {/* Status Pills */}
        <div className="d-flex flex-wrap align-items-center gap-2 mb-3">
          {statusTabs.map((tab) => {
            const isActive = statusFilter === tab.value;
            return (
              <button
                key={tab.value}
                type="button"
                className="btn btn-sm rounded-pill px-3 py-1.5 d-flex align-items-center gap-1.5 shadow-sm"
                style={{
                  backgroundColor: isActive ? "#715DF2" : "#ffffff",
                  borderColor: isActive ? "#715DF2" : "#cbd5e1",
                  color: isActive ? "#ffffff" : "#1e293b",
                  fontWeight: "600",
                  fontSize: "13px",
                  transition: "all 0.2s ease",
                }}
                onClick={() => setStatusFilter(tab.value)}
              >
                <span style={{ color: isActive ? "#ffffff" : "#1e293b" }}>{tab.label}</span>
                {tab.count !== undefined && (
                  <span
                    className="badge rounded-pill ms-1"
                    style={{
                      fontSize: "11px",
                      fontWeight: "700",
                      backgroundColor: isActive ? "#ffffff" : "#f1f5f9",
                      color: isActive ? "#715DF2" : "#475569",
                      border: isActive ? "none" : "1px solid #e2e8f0",
                    }}
                  >
                    {tab.count}
                  </span>
                )}
              </button>
            );
          })}
        </div>

        {/* Search Bar */}
        <form onSubmit={handleSearchSubmit} className="row g-2 align-items-center">
          <div className="col-md-6 col-lg-5">
            <div className="input-group">
              <span className="input-group-text bg-white border-end-0 text-muted">
                <FiSearch size={16} />
              </span>
              <input
                type="text"
                className="form-control border-start-0 ps-0"
                placeholder="Search by Request ID, Buyer Name, Phone, Email, Product..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                style={{ fontSize: "14px" }}
              />
              <button
                type="submit"
                className="btn btn-primary px-3"
                style={{ backgroundColor: "#715DF2", borderColor: "#715DF2" }}
              >
                Search
              </button>
            </div>
          </div>
          {searchQuery && (
            <div className="col-auto">
              <button
                type="button"
                className="btn btn-link text-muted btn-sm p-0 fs-13"
                onClick={() => {
                  setSearchQuery("");
                  setTimeout(() => fetchProductRequests(1), 50);
                }}
              >
                Clear Search
              </button>
            </div>
          )}
        </form>
      </div>

      {/* Table Content */}
      <div className="card-body p-0">
        {loading ? (
          <div className="text-center py-5">
            <div className="spinner-border text-primary" role="status">
              <span className="visually-hidden">Loading...</span>
            </div>
            <p className="mt-2 text-muted fs-14">Loading product requests...</p>
          </div>
        ) : requests.length === 0 ? (
          <div className="text-center py-5 text-muted">
            <FiAlertCircle size={44} className="mb-2 text-warning" />
            <h5 className="fw-bold text-dark">No Product Requests Found</h5>
            <p className="fs-14">
              {searchQuery || statusFilter !== "ALL"
                ? "Try adjusting your search query or status filter."
                : "There are currently no product requests in the system."}
            </p>
          </div>
        ) : (
          <div className="table-responsive">
            <table className="table table-hover align-middle mb-0 custom-admin-table">
              <thead style={{ backgroundColor: "#f8fafc", color: "#334155", fontSize: "13px", fontWeight: "700" }}>
                <tr>
                  <th className="ps-3 pe-2 text-center" style={{ width: "70px", minWidth: "70px", whiteSpace: "nowrap" }}>#</th>
                  <th>Request ID</th>
                  <th>Buyer Name</th>
                  <th>Seller / Status</th>
                  <th className="text-center">Quantity</th>
                  <th>Total MRP</th>
                  <th className="text-center">Request Status</th>
                  <th>Request Date</th>
                  <th className="text-center pe-4" style={{ width: "120px" }}>Action</th>
                </tr>
              </thead>
              <tbody style={{ fontSize: "13.5px" }}>
                {requests.map((reqItem, idx) => {
                  const rowNumber = (pagination.page - 1) * pagination.limit + idx + 1;

                  // Buyer Info
                  const buyerId = reqItem.buyerId?._id || reqItem.buyerId;
                  const buyerName =
                    reqItem.deliveryAddress?.name ||
                    reqItem.buyerId?.name ||
                    reqItem.buyerId?.basicInformation?.fullName ||
                    "Customer";

                  const buyerPhone =
                    reqItem.deliveryAddress?.phone ||
                    reqItem.deliveryAddress?.mobile ||
                    reqItem.buyerId?.mobile ||
                    "";

                  // Seller Name / Status & ID for Redirection
                  let sellerDisplay = "No Seller Assigned";
                  let sellerId = null;

                  const confirmedSeller = reqItem.sellers?.find(
                    (s) =>
                      s.status === "CONFIRMED" ||
                      s.status === "PROCESSING" ||
                      s.status === "OUT_FOR_DELIVERY" ||
                      s.status === "COMPLETED" ||
                      s.status === "DELIVERED"
                  );

                  if (confirmedSeller?.sellerId?.basicInformation?.shopName) {
                    sellerDisplay = confirmedSeller.sellerId.basicInformation.shopName;
                    sellerId = confirmedSeller.sellerId._id || confirmedSeller.sellerId;
                  } else if (reqItem.selectedQuotationId?.sellerId?.basicInformation?.shopName) {
                    sellerDisplay = reqItem.selectedQuotationId.sellerId.basicInformation.shopName;
                    sellerId = reqItem.selectedQuotationId.sellerId._id || reqItem.selectedQuotationId.sellerId;
                  } else if (reqItem.sellers && reqItem.sellers.length > 0) {
                    const participatedCount = reqItem.sellers.filter(
                      (s) => s.status === "PARTICIPATED" || s.quotationId
                    ).length;
                    sellerDisplay =
                      participatedCount > 0
                        ? `${participatedCount} Seller${participatedCount > 1 ? "s" : ""} Quoted`
                        : `${reqItem.sellers.length} Seller${reqItem.sellers.length > 1 ? "s" : ""} Notified`;
                  }

                  // Dynamic month and year from order createdAt
                  const orderDate = new Date(reqItem.createdAt || Date.now());
                  const orderMonth = orderDate.getMonth() + 1;
                  const orderYear = orderDate.getFullYear();

                  const isOrderTab =
                    statusFilter === "CONFIRMED" ||
                    statusFilter === "OUT_FOR_DELIVERY" ||
                    statusFilter === "COMPLETED" ||
                    ["CONFIRMED", "PROCESSING", "OUT_FOR_DELIVERY", "COMPLETED", "DELIVERED"].includes(
                      reqItem.status?.toUpperCase()
                    );

                  // Quantity calculation
                  const totalItemsCount = reqItem.items?.length || 0;
                  const totalQuantity =
                    reqItem.items?.reduce(
                      (sum, it) => sum + Number(it.requestedQuantity || it.quantity || 1),
                      0
                    ) || (reqItem.prescriptionUrls?.length ? 1 : 0);

                  // Total MRP calculation
                  const totalMrp =
                    reqItem.items?.reduce(
                      (sum, it) =>
                        sum +
                        Number(it.mrp || it.price || 0) *
                        Number(it.requestedQuantity || it.quantity || 1),
                      0
                    ) || 0;

                  const isPrescription =
                    reqItem.requestType?.toUpperCase() === "PRESCRIPTION" ||
                    (!reqItem.items || reqItem.items.length === 0);

                  return (
                    <tr key={reqItem._id || idx}>
                      <td className="ps-3 pe-2 text-center fw-bold text-muted" style={{ width: "70px", minWidth: "70px", whiteSpace: "nowrap" }}>{rowNumber}</td>
                      <td>
                        <div className="d-flex align-items-center gap-1.5">
                          <strong style={{ color: "#715DF2" }}>
                            {reqItem.orderId || reqItem._id?.slice(-8)}
                          </strong>
                        </div>
                        <span
                          className="badge rounded-pill mt-1 d-inline-block"
                          style={{
                            backgroundColor: isPrescription ? "#EEF2FF" : "#F1F5F9",
                            color: isPrescription ? "#4F46E5" : "#334155",
                            border: isPrescription ? "1px solid #C7D2FE" : "1px solid #CBD5E1",
                            fontSize: "11px",
                            fontWeight: "700",
                            padding: "3px 8px",
                          }}
                        >
                          {isPrescription ? "Prescription" : "Product Req"}
                        </span>
                      </td>

                      <td>
                        {buyerId ? (
                          <Link
                            to={getBuyerTargetLocation(buyerId, reqItem)}
                            className="fw-bold text-decoration-none d-inline-flex align-items-center gap-1.5"
                            style={{ color: "#1e293b", transition: "color 0.2s ease" }}
                            onMouseEnter={(e) => (e.currentTarget.style.color = "#715DF2")}
                            onMouseLeave={(e) => (e.currentTarget.style.color = "#1e293b")}
                            title="View Buyer Order/Request Details"
                          >
                            <span>{buyerName}</span>
                            <FiExternalLink size={11} style={{ color: "#715DF2" }} />
                          </Link>
                        ) : (
                          <div className="fw-bold text-dark">{buyerName}</div>
                        )}
                        {buyerPhone && (
                          <div className="text-muted font-11">📞 {buyerPhone}</div>
                        )}
                      </td>

                      <td>
                        {sellerId && isOrderTab ? (
                          <Link
                            to={`/adminOrders/${sellerId}?month=${orderMonth}&year=${orderYear}&tab=ORDERS`}
                            className="fw-bold text-decoration-none d-inline-flex align-items-center gap-1.5"
                            style={{ color: "#1e293b", transition: "color 0.2s ease" }}
                            onMouseEnter={(e) => (e.currentTarget.style.color = "#715DF2")}
                            onMouseLeave={(e) => (e.currentTarget.style.color = "#1e293b")}
                            title="View Seller Order History"
                          >
                            <span>{sellerDisplay}</span>
                            <FiExternalLink size={11} style={{ color: "#715DF2" }} />
                          </Link>
                        ) : (
                          <div className="fw-600 text-dark">{sellerDisplay}</div>
                        )}
                        {reqItem.quotationsCount > 0 && (
                          <span
                            className="badge rounded-pill mt-1 d-inline-block"
                            style={{
                              backgroundColor: "#FAF5FF",
                              color: "#715DF2",
                              border: "1px solid #E9D5FF",
                              fontSize: "11px",
                              fontWeight: "700",
                              padding: "2px 8px",
                            }}
                          >
                            {reqItem.quotationsCount} Quote{reqItem.quotationsCount > 1 ? "s" : ""} Received
                          </span>
                        )}
                      </td>

                      <td className="text-center">
                        <span className="badge bg-light text-dark border px-2.5 py-1 fs-12 fw-bold">
                          {totalQuantity} {totalItemsCount > 1 ? `(${totalItemsCount} items)` : "Qty"}
                        </span>
                      </td>

                      <td>
                        <strong className="text-dark fs-14">
                          {totalMrp > 0 ? `₹${totalMrp.toLocaleString("en-IN")}` : "Prescription"}
                        </strong>
                      </td>

                      <td className="text-center">
                        {getStatusBadge(reqItem.status)}
                      </td>

                      <td className="text-muted fs-13">
                        {formatDate(reqItem.createdAt)}
                      </td>

                      <td className="text-center pe-4">
                        <button
                          type="button"
                          className="btn btn-sm btn-primary d-inline-flex align-items-center gap-1.5 px-3 py-1.5 rounded-pill shadow-sm"
                          style={{
                            backgroundColor: "#715DF2",
                            borderColor: "#715DF2",
                            fontSize: "13px",
                            fontWeight: "600",
                          }}
                          onClick={() => {
                            setSelectedRequest(reqItem);
                            setShowDetailModal(true);
                          }}
                          title="View Full Product Request Details"
                        >
                          <FiEye size={14} />
                        </button>
                      </td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
        )}
      </div>

      {/* Pagination Footer */}
      {!loading && pagination.total > 0 && (
        <div className="p-3.5 border-top bg-light d-flex flex-wrap align-items-center justify-content-between gap-3">
          <span className="text-dark fs-13" style={{ fontWeight: "500" }}>
            Showing <strong>{(pagination.page - 1) * pagination.limit + 1}</strong> to{" "}
            <strong>
              {Math.min(pagination.page * pagination.limit, pagination.total)}
            </strong>{" "}
            of <strong>{pagination.total}</strong> product requests
          </span>

          {pagination.totalPages > 1 && (
            <div className="d-flex align-items-center" style={{ gap: "6px" }}>
              <button
                type="button"
                className="btn btn-sm rounded-circle p-0 shadow-sm"
                style={{
                  width: "36px",
                  height: "36px",
                  minWidth: "36px",
                  flexShrink: 0,
                  backgroundColor: "#ffffff",
                  border: "1px solid #cbd5e1",
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: pagination.page <= 1 ? "not-allowed" : "pointer",
                  transition: "all 0.15s ease",
                }}
                disabled={pagination.page <= 1}
                onClick={() => fetchProductRequests(pagination.page - 1)}
                title="Previous Page"
              >
                <span
                  style={{
                    color: pagination.page <= 1 ? "#cbd5e1" : "#1e293b",
                    fontSize: "14px",
                    fontWeight: "900",
                    lineHeight: 1,
                    whiteSpace: "nowrap",
                  }}
                >
                  &#10094;
                </span>
              </button>

              {Array.from({ length: pagination.totalPages }, (_, i) => i + 1)
                .filter((p) => {
                  return (
                    p === 1 ||
                    p === pagination.totalPages ||
                    Math.abs(p - pagination.page) <= 1
                  );
                })
                .map((p, pIdx, arr) => {
                  const prev = arr[pIdx - 1];
                  const showEllipsis = prev && p - prev > 1;
                  const isCurrent = pagination.page === p;

                  return (
                    <React.Fragment key={p}>
                      {showEllipsis && (
                        <span
                          className="text-muted px-1"
                          style={{ fontSize: "14px", fontWeight: "600", userSelect: "none" }}
                        >
                          ...
                        </span>
                      )}
                      <button
                        type="button"
                        className="btn btn-sm rounded-circle p-0 shadow-sm"
                        style={{
                          width: "36px",
                          height: "36px",
                          minWidth: "36px",
                          flexShrink: 0,
                          backgroundColor: isCurrent ? "#715DF2" : "#ffffff",
                          border: isCurrent ? "1px solid #715DF2" : "1px solid #cbd5e1",
                          display: "inline-flex",
                          alignItems: "center",
                          justifyContent: "center",
                          padding: 0,
                          cursor: "pointer",
                          transition: "all 0.15s ease",
                        }}
                        onClick={() => fetchProductRequests(p)}
                      >
                        <span
                          style={{
                            color: isCurrent ? "#ffffff" : "#1e293b",
                            fontWeight: "700",
                            fontSize: "13px",
                            whiteSpace: "nowrap",
                            display: "inline-block",
                            lineHeight: 1,
                          }}
                        >
                          {p}
                        </span>
                      </button>
                    </React.Fragment>
                  );
                })}

              <button
                type="button"
                className="btn btn-sm rounded-circle p-0 shadow-sm"
                style={{
                  width: "36px",
                  height: "36px",
                  minWidth: "36px",
                  flexShrink: 0,
                  backgroundColor: "#ffffff",
                  border: "1px solid #cbd5e1",
                  display: "inline-flex",
                  alignItems: "center",
                  justifyContent: "center",
                  cursor: pagination.page >= pagination.totalPages ? "not-allowed" : "pointer",
                  transition: "all 0.15s ease",
                }}
                disabled={pagination.page >= pagination.totalPages}
                onClick={() => fetchProductRequests(pagination.page + 1)}
                title="Next Page"
              >
                <span
                  style={{
                    color: pagination.page >= pagination.totalPages ? "#cbd5e1" : "#1e293b",
                    fontSize: "14px",
                    fontWeight: "900",
                    lineHeight: 1,
                    whiteSpace: "nowrap",
                  }}
                >
                  &#10095;
                </span>
              </button>
            </div>
          )}
        </div>
      )}

      {/* ===================== MODAL: COMPLETE PRODUCT REQUEST DETAILS ===================== */}
      {showDetailModal && selectedRequest && (
        <div
          style={{
            position: "fixed",
            inset: 0,
            backgroundColor: "rgba(15, 23, 42, 0.65)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            zIndex: 1050,
            padding: "1rem",
            backdropFilter: "blur(4px)",
          }}
          onClick={() => setShowDetailModal(false)}
        >
          <div
            style={{
              backgroundColor: "#ffffff",
              borderRadius: "16px",
              maxWidth: "960px",
              width: "100%",
              boxShadow: "0 25px 50px -12px rgba(15, 23, 42, 0.25)",
              position: "relative",
              overflow: "hidden",
              maxHeight: "90vh",
              display: "flex",
              flexDirection: "column",
              border: "1px solid #E2E8F0",
            }}
            onClick={(e) => e.stopPropagation()}
          >
            {/* Modal Header */}
            <div className="d-flex align-items-center justify-content-between px-4 py-3 border-bottom bg-white">
              <div>
                <div className="d-flex flex-wrap align-items-center gap-2 mb-1">
                  <span
                    className="badge rounded-pill text-white fw-semibold"
                    style={{ backgroundColor: "#715DF2", fontSize: "0.75rem", padding: "0.35em 0.75em" }}
                  >
                    Request Details
                  </span>
                  <h5 className="m-0 fw-bold text-dark" style={{ fontSize: "1.15rem" }}>
                    Request #{selectedRequest.orderId || selectedRequest._id?.slice(-8)}
                  </h5>
                  {getStatusBadge(selectedRequest.status)}
                </div>
                <div className="text-secondary small">
                  Created on {formatDate(selectedRequest.createdAt)} &nbsp;•&nbsp; Type:{" "}
                  <strong className="text-dark">{selectedRequest.requestType || "PRODUCT"}</strong>
                </div>
              </div>

              <button
                type="button"
                aria-label="Close"
                className="btn btn-light rounded-circle p-0 d-flex align-items-center justify-content-center text-secondary"
                onClick={() => setShowDetailModal(false)}
                style={{ width: "36px", height: "36px", transition: "all 0.2s" }}
              >
                <FiX size={18} />
              </button>
            </div>

            {/* Modal Scrollable Body */}
            <div className="p-4" style={{ overflowY: "auto" }}>
              {/* Top Action Banner: Quotations Status */}
              <div
                className="p-3 mb-4 rounded-3 d-flex flex-column flex-sm-row align-items-sm-center justify-content-between gap-3"
                style={{ backgroundColor: "#F8FAFC", border: "1px solid #E2E8F0" }}
              >
                <div>
                  <span
                    className="text-muted fw-bold text-uppercase d-block mb-1"
                    style={{ fontSize: "0.7rem", letterSpacing: "0.5px" }}
                  >
                    Quotations Status
                  </span>
                  <div className="fw-semibold text-dark fs-6">
                    {selectedRequest.quotationsCount > 0
                      ? `${selectedRequest.quotationsCount} Quotation(s) Received from Sellers`
                      : "No quotations received yet for this request"}
                  </div>
                </div>

                <button
                  type="button"
                  className="btn btn-sm d-inline-flex align-items-center justify-content-center gap-2 px-3 py-2 rounded-pill text-white shadow-sm border-0 flex-shrink-0"
                  style={{ backgroundColor: "#715DF2", fontWeight: "600", fontSize: "0.825rem" }}
                  onClick={() => {
                    setShowDetailModal(false);
                    const buyerId = selectedRequest.buyerId?._id || selectedRequest.buyerId || "unknown";
                    navigate(`/userBooking/${buyerId}/request/${selectedRequest._id}/quotations`);
                  }}
                >
                  <FiEye size={15} />
                  <span>View All Quotations</span>
                  <FiExternalLink size={13} />
                </button>
              </div>

              {/* Buyer Details & Delivery Address */}
              {(() => {
                const bName =
                  selectedRequest.deliveryAddress?.name ||
                  selectedRequest.buyerId?.name ||
                  selectedRequest.buyerId?.basicInformation?.fullName ||
                  "Buyer";

                const bPhone =
                  selectedRequest.deliveryAddress?.phone ||
                  selectedRequest.deliveryAddress?.mobile ||
                  selectedRequest.buyerId?.mobile ||
                  "N/A";

                const bEmail =
                  selectedRequest.deliveryAddress?.email ||
                  selectedRequest.buyerId?.email ||
                  "N/A";

                const addressParts = [
                  selectedRequest.deliveryAddress?.houseNo,
                  selectedRequest.deliveryAddress?.addressLine || selectedRequest.deliveryAddress?.address,
                  selectedRequest.deliveryAddress?.landmark ? `Near ${selectedRequest.deliveryAddress.landmark}` : "",
                  selectedRequest.deliveryAddress?.city,
                  selectedRequest.deliveryAddress?.state,
                  selectedRequest.deliveryAddress?.pincode ? `- ${selectedRequest.deliveryAddress.pincode}` : "",
                ].filter(Boolean);

                const fullAddress =
                  addressParts.length > 0
                    ? addressParts.join(", ")
                    : selectedRequest.deliveryAddress?.address || "Address not provided";

                const mapLink = `https://www.google.com/maps/search/?api=1&query=${encodeURIComponent(fullAddress)}`;

                return (
                  <div className="p-3.5 p-md-4 mb-4 border rounded-3 bg-white">
                    <h6 className="fw-bold mb-3 text-dark d-flex align-items-center gap-2" style={{ fontSize: "0.95rem" }}>
                      <FiUser style={{ color: "#715DF2" }} size={18} /> Buyer &amp; Delivery Information
                    </h6>
                    <div className="row g-3 align-items-stretch">
                      {/* Contact Information */}
                      <div className="col-lg-5 d-flex flex-column">
                        <div className="p-3 rounded-3 border bg-light h-100 d-flex flex-column justify-content-between gap-3">
                          <div>
                            <span className="text-muted fw-bold text-uppercase d-block" style={{ fontSize: "0.7rem" }}>
                              Customer Name
                            </span>
                            {selectedRequest.buyerId ? (
                              <Link
                                to={getBuyerTargetLocation(
                                  selectedRequest.buyerId?._id || selectedRequest.buyerId,
                                  selectedRequest
                                )}
                                className="text-dark fw-bold d-inline-flex align-items-center gap-1.5 text-decoration-none mt-0.5"
                                style={{ fontSize: "0.95rem", transition: "color 0.15s ease" }}
                                onMouseEnter={(e) => (e.currentTarget.style.color = "#715DF2")}
                                onMouseLeave={(e) => (e.currentTarget.style.color = "#1e293b")}
                                title="View Buyer Order/Request Details"
                                onClick={() => setShowDetailModal(false)}
                              >
                                <span>{bName}</span>
                                <FiExternalLink size={13} style={{ color: "#715DF2" }} />
                              </Link>
                            ) : (
                              <span className="text-dark fw-bold" style={{ fontSize: "0.95rem" }}>
                                {bName}
                              </span>
                            )}
                          </div>

                          <div className="d-flex flex-column gap-2 pt-2 border-top">
                            <div>
                              <span className="text-muted fw-bold text-uppercase d-block" style={{ fontSize: "0.7rem" }}>
                                Phone Number
                              </span>
                              <div className="fw-semibold small text-dark mt-0.5">
                                {bPhone !== "N/A" ? (
                                  <a href={`tel:${bPhone}`} className="text-decoration-none text-dark">
                                    📞 {bPhone}
                                  </a>
                                ) : (
                                  <span className="text-muted">N/A</span>
                                )}
                              </div>
                            </div>

                            <div>
                              <span className="text-muted fw-bold text-uppercase d-block" style={{ fontSize: "0.7rem" }}>
                                Email Address
                              </span>
                              <div className="small text-break mt-0.5">
                                {bEmail !== "N/A" ? (
                                  <a href={`mailto:${bEmail}`} className="text-decoration-none fw-semibold" style={{ color: "#715DF2" }}>
                                    ✉️ {bEmail}
                                  </a>
                                ) : (
                                  <span className="text-muted">N/A</span>
                                )}
                              </div>
                            </div>
                          </div>
                        </div>
                      </div>

                      {/* Delivery Address */}
                      <div className="col-lg-7 d-flex flex-column">
                        <div className="p-3 rounded-3 border bg-light h-100 d-flex flex-column justify-content-between gap-3">
                          <div>
                            <span className="text-muted fw-bold text-uppercase d-flex align-items-center gap-1 mb-1" style={{ fontSize: "0.7rem" }}>
                              <FiMapPin style={{ color: "#715DF2" }} /> Delivery Address
                            </span>
                            <p className="text-dark mb-0 fw-normal small lh-base" style={{ minHeight: "3rem" }}>
                              {fullAddress}
                            </p>
                          </div>

                          <div className="pt-2 border-top d-flex align-items-center justify-content-between flex-wrap gap-2">
                            <span className="text-muted" style={{ fontSize: "0.75rem" }}>
                              Location Coordinates / Map
                            </span>
                            <a
                              href={mapLink}
                              target="_blank"
                              rel="noreferrer"
                              className="btn btn-sm d-inline-flex align-items-center gap-1.5 px-3 py-1.5 rounded-pill text-white shadow-sm border-0"
                              style={{ backgroundColor: "#715DF2", fontSize: "0.78rem", fontWeight: "600" }}
                            >
                              <FiMapPin size={13} />
                              <span>Open in Maps</span>
                              <FiExternalLink size={11} />
                            </a>
                          </div>
                        </div>
                      </div>
                    </div>
                  </div>
                );
              })()}

              {/* Requested Products Section */}
              <div className="d-flex align-items-center justify-content-between mb-2">
                <h6 className="fw-bold text-dark m-0 d-flex align-items-center gap-2" style={{ fontSize: "0.95rem" }}>
                  <FiPackage style={{ color: "#715DF2" }} size={17} /> Requested Products &amp; Items
                </h6>
                <span className="badge rounded-pill bg-light text-secondary border px-2.5 py-1" style={{ fontSize: "0.75rem" }}>
                  {selectedRequest.items?.length || 0} Item(s) Requested
                </span>
              </div>

              <div
                className="table-responsive mb-4"
                style={{
                  overflowX: "auto",
                  WebkitOverflowScrolling: "touch",
                  scrollbarWidth: "thin",
                }}
              >
                <table
                  className="table align-middle mb-0"
                  style={{
                    minWidth: "750px",
                    borderCollapse: "collapse",
                    border: "1px solid #cbd5e1",
                    backgroundColor: "#ffffff",
                  }}
                >
                  <thead>
                    <tr style={{ backgroundColor: "#f8fafc", borderBottom: "1px solid #cbd5e1" }}>
                      <th className="text-center" style={{ width: "45px", border: "1px solid #cbd5e1", padding: "10px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>#</th>
                      <th style={{ border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>Product Name</th>
                      <th className="text-center" style={{ width: "80px", border: "1px solid #cbd5e1", padding: "10px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>Qty</th>
                      <th className="text-end" style={{ width: "110px", border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>MRP (₹)</th>
                      <th className="text-center" style={{ width: "160px", border: "1px solid #cbd5e1", padding: "10px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>Prescription</th>
                      <th className="text-end pe-3" style={{ width: "130px", border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.825rem", color: "#1e293b", fontWeight: "700" }}>Subtotal (₹)</th>
                    </tr>
                  </thead>
                  <tbody style={{ fontSize: "0.85rem" }}>
                    {selectedRequest.items && selectedRequest.items.length > 0 ? (
                      selectedRequest.items.map((it, iIdx) => {
                        const itemQty = Number(it.requestedQuantity || it.quantity || 1);
                        const unitMrp = Number(it.mrp || it.price || 0);
                        const subtotal = unitMrp * itemQty;

                        const isPrescriptionRequired = Boolean(
                          it.prescriptionRequired === true ||
                          it.prescriptionRequired === "Yes" ||
                          it.prescription_required === true ||
                          it.prescription_required === "Yes" ||
                          it.prescription === "Yes"
                        );

                        // Extract all relevant prescription URLs for this item ONLY if prescription is required
                        const itemRxUrls = [];
                        if (isPrescriptionRequired) {
                          if (it.prescriptionUrl) {
                            itemRxUrls.push(it.prescriptionUrl);
                          }
                          if (Array.isArray(it.prescriptionUrls)) {
                            it.prescriptionUrls.forEach((u) => {
                              if (u && !itemRxUrls.includes(u)) itemRxUrls.push(u);
                            });
                          }
                          if (Array.isArray(it.prescriptionDetails)) {
                            it.prescriptionDetails.forEach((d) => {
                              if (d?.prescriptionUrl && !itemRxUrls.includes(d.prescriptionUrl)) {
                                itemRxUrls.push(d.prescriptionUrl);
                              }
                            });
                          }
                          // Fallback: If no item-level URL but request has prescriptionUrls
                          if (itemRxUrls.length === 0 && selectedRequest.prescriptionUrls && selectedRequest.prescriptionUrls.length > 0) {
                            if (Array.isArray(selectedRequest.prescriptionUrls)) {
                              selectedRequest.prescriptionUrls.forEach((u) => {
                                if (u && !itemRxUrls.includes(u)) itemRxUrls.push(u);
                              });
                            }
                          }
                        }

                        return (
                          <tr key={iIdx}>
                            <td className="text-center text-muted fw-semibold" style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px" }}>
                              {iIdx + 1}
                            </td>
                            <td style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px 12px" }}>
                              <span className="fw-bold text-dark">{it.productName}</span>
                            </td>
                            <td className="text-center fw-bold text-dark" style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px" }}>
                              {itemQty}
                            </td>
                            <td className="text-end fw-semibold text-dark" style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px 12px" }}>
                              ₹{unitMrp.toLocaleString("en-IN")}
                            </td>

                            {/* Prescription Column */}
                            <td className="text-center" style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px" }}>
                              {isPrescriptionRequired && itemRxUrls.length > 0 ? (
                                <div className="d-flex flex-column gap-1.5 align-items-center justify-content-center">
                                  {itemRxUrls.map((pUrl, pIdx) => (
                                    <a
                                      key={pIdx}
                                      href={pUrl}
                                      target="_blank"
                                      rel="noreferrer"
                                      className="btn btn-sm d-inline-flex align-items-center gap-1.5 px-3 py-1.5 rounded-pill shadow-sm"
                                      style={{
                                        backgroundColor: "#ffffff",
                                        color: "#715DF2",
                                        border: "1.5px solid #715DF2",
                                        fontSize: "0.78rem",
                                        fontWeight: "700",
                                        textDecoration: "none",
                                        whiteSpace: "nowrap",
                                        lineHeight: "1.2",
                                        transition: "all 0.2s ease",
                                      }}
                                      title="View Uploaded Prescription File"
                                    >
                                      <FiFileText size={13} style={{ color: "#715DF2" }} />
                                      <span style={{ color: "#715DF2", fontWeight: "700", fontSize: "0.78rem" }}>
                                        View File {itemRxUrls.length > 1 ? `#${pIdx + 1}` : ""}
                                      </span>
                                      <FiExternalLink size={11} style={{ color: "#715DF2" }} />
                                    </a>
                                  ))}
                                </div>
                              ) : (
                                <span className="text-muted small">—</span>
                              )}
                            </td>

                            <td className="text-end pe-3 fw-bold text-dark" style={{ border: "1px solid #cbd5e1", verticalAlign: "middle", padding: "10px 12px" }}>
                              ₹{subtotal.toLocaleString("en-IN")}
                            </td>
                          </tr>
                        );
                      })
                    ) : (
                      <tr>
                        <td colSpan="6" className="text-center text-muted py-4 small" style={{ border: "1px solid #cbd5e1" }}>
                          <div className="d-flex flex-column align-items-center gap-2">
                            <span className="fw-semibold text-dark">Prescription-based request (No individual product listing)</span>
                            {selectedRequest.prescriptionUrls && selectedRequest.prescriptionUrls.length > 0 && (
                              <div className="d-flex flex-wrap gap-2 justify-content-center mt-1">
                                {selectedRequest.prescriptionUrls.map((pUrl, pIdx) => (
                                  <a
                                    key={pIdx}
                                    href={pUrl}
                                    target="_blank"
                                    rel="noreferrer"
                                    className="btn btn-sm d-inline-flex align-items-center gap-1.5 px-3 py-1.5 rounded-pill bg-white border shadow-sm"
                                    style={{ color: "#715DF2", borderColor: "#CBD5E1", fontSize: "0.78rem", fontWeight: "600" }}
                                  >
                                    <FiEye size={13} style={{ color: "#715DF2" }} />
                                    <span style={{ color: "#715DF2", fontWeight: "700", fontSize: "0.78rem" }}>
                                      View File {selectedRequest.prescriptionUrls.length > 1 ? `#${pIdx + 1}` : ""}
                                    </span>
                                    <FiExternalLink size={11} style={{ color: "#715DF2" }} />
                                  </a>
                                ))}
                              </div>
                            )}
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                  {selectedRequest.items && selectedRequest.items.length > 0 && (
                    <tfoot style={{ backgroundColor: "#F8FAFC" }}>
                      <tr style={{ borderTop: "2px solid #cbd5e1" }}>
                        <td colSpan="5" className="text-end fw-bold text-dark ps-3 py-3" style={{ border: "1px solid #cbd5e1", fontSize: "0.85rem" }}>
                          Total Estimated MRP:
                        </td>
                        <td className="text-end pe-3 fw-bold py-3" style={{ border: "1px solid #cbd5e1", color: "#715DF2", fontSize: "1rem" }}>
                          ₹
                          {selectedRequest.items
                            .reduce(
                              (sum, it) =>
                                sum +
                                Number(it.mrp || it.price || 0) * Number(it.requestedQuantity || it.quantity || 1),
                              0
                            )
                            .toLocaleString("en-IN")}
                        </td>
                      </tr>
                    </tfoot>
                  )}
                </table>
              </div>

              {/* Participating Sellers Section */}
              {selectedRequest.sellers && selectedRequest.sellers.length > 0 && (
                <div>
                  <div className="d-flex align-items-center justify-content-between mb-2">
                    <h6 className="fw-bold text-dark m-0 d-flex align-items-center gap-2" style={{ fontSize: "0.95rem" }}>
                      <FiShoppingBag style={{ color: "#715DF2" }} size={17} /> Notified / Participating Sellers
                    </h6>
                    <span className="badge rounded-pill bg-light text-secondary border px-2.5 py-1" style={{ fontSize: "0.75rem" }}>
                      {selectedRequest.sellers.length} total
                    </span>
                  </div>

                  <div
                    className="table-responsive mb-2"
                    style={{
                      overflowX: "auto",
                      WebkitOverflowScrolling: "touch",
                      scrollbarWidth: "thin",
                    }}
                  >
                    <table
                      className="table table-sm align-middle mb-0"
                      style={{
                        minWidth: "700px",
                        borderCollapse: "collapse",
                        border: "1px solid #cbd5e1",
                        backgroundColor: "#ffffff",
                      }}
                    >
                      <thead>
                        <tr style={{ backgroundColor: "#F8FAFC", borderBottom: "1px solid #cbd5e1" }}>
                          <th className="text-center" style={{ width: "40px", border: "1px solid #cbd5e1", padding: "10px", fontSize: "0.8rem", color: "#1e293b", fontWeight: "700" }}>#</th>
                          <th style={{ border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.8rem", color: "#1e293b", fontWeight: "700" }}>Pharmacy / Seller</th>
                          <th style={{ border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.8rem", color: "#1e293b", fontWeight: "700" }}>Contact</th>
                          <th className="text-center" style={{ border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.8rem", color: "#1e293b", fontWeight: "700" }}>Status</th>
                          <th className="text-end pe-3" style={{ border: "1px solid #cbd5e1", padding: "10px 12px", fontSize: "0.8rem", color: "#1e293b", fontWeight: "700" }}>Distance</th>
                        </tr>
                      </thead>
                      <tbody style={{ fontSize: "0.825rem" }}>
                        {selectedRequest.sellers.map((sItem, sIdx) => {
                          const sInfo = sItem.sellerId?.basicInformation;
                          const sContact = sItem.sellerId?.contactInformation;
                          return (
                            <tr key={sIdx}>
                              <td className="text-center text-muted fw-semibold" style={{ border: "1px solid #cbd5e1", padding: "10px", verticalAlign: "middle" }}>{sIdx + 1}</td>
                              <td style={{ border: "1px solid #cbd5e1", padding: "10px 12px", verticalAlign: "middle" }}>
                                <span className="fw-semibold text-dark">{sInfo?.shopName || "Seller"}</span>
                                {sInfo?.contactPersonName && (
                                  <span className="text-muted d-block" style={{ fontSize: "0.75rem" }}>
                                    {sInfo.contactPersonName}
                                  </span>
                                )}
                              </td>
                              <td style={{ border: "1px solid #cbd5e1", padding: "10px 12px", verticalAlign: "middle" }} className="text-dark">{sContact?.Mobileprimary || "N/A"}</td>
                              <td className="text-center" style={{ border: "1px solid #cbd5e1", padding: "10px 12px", verticalAlign: "middle" }}>
                                <span
                                  className={`badge rounded-pill ${sItem.status === "CONFIRMED"
                                      ? "bg-success-subtle text-success border border-success-subtle"
                                      : sItem.status === "PARTICIPATED"
                                        ? "bg-primary-subtle text-primary border border-primary-subtle"
                                        : "bg-light text-secondary border"
                                    } px-2.5 py-1`}
                                  style={{ fontSize: "0.72rem" }}
                                >
                                  {sItem.status?.replace(/_/g, " ") || "Notified"}
                                </span>
                              </td>
                              <td className="text-end pe-3 text-muted" style={{ border: "1px solid #cbd5e1", padding: "10px 12px", verticalAlign: "middle" }}>
                                {sItem.distanceKm ? `${sItem.distanceKm} km` : "N/A"}
                              </td>
                            </tr>
                          );
                        })}
                      </tbody>
                    </table>
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminProductRequestsLayer;
